// Tiempos del chip (ms): ataque de 0 a máximo y caída de 96 dB, según la velocidad (0-15).
const ATTACK_MS = [Infinity, 2826, 1413, 706, 353, 176, 88, 44, 22, 11, 5.5, 2.8, 1.4, 0.7, 0.35, 0.05];
const DECAY_MS = [Infinity, 39280, 19640, 9820, 4910, 2455, 1227, 614, 307, 153, 77, 38, 19, 9.6, 4.8, 2.4];
